    ("سخت زمينن ۾ کارين (Ridges) تي پوکڻ جو چڻي کي ڇا فائدو آهي؟", "سخت زمیناں وچ کھیلیاں (Ridges) اُتے کاشت کرن دا چنے نوں کیہہ فائدہ ہے؟ کتنا فائدہ ہے؟ کھیلیاں اُتے کاشت کرن نال پاݨی جڑاں وچ نہیں کھڑوندا تے بوٹے سڑن توں بچ جاندے نیں۔", "کاشت دی تیاری تے کاشت"),
    ("پاڪستان جي ڪل چڻي جو ڪيترو سيڪڙو پنجاب ۾ پيدا ٿئي ٿو؟", "پاکستان دے کُل چنے دا کِنّا فیصد حصہ پنجاب وچ پیدا ہوندا ہے؟ پاکستان دا 80 توں 85 فیصد چنا پنجاب وچ پیدا ہوندا ہے۔", "صوبائي مرڪز: پنجاب"),
    ("پنجاب جو ڪهڙو علائقو چڻي جو مرڪز سڏجي ٿو؟", "پنجاب دا کیہڑا علاقہ چنے دا مرکز اکھواندا ہے؟ تھل دا علاقہ، جیہدے وچ بھکر، لیہہ، خوشاب تے میانوالی دے ضلعے آندے نیں۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل جو علائقو چڻي جي پوک لاءِ ڇو مشهور آهي؟", "تھل دا علاقہ چنے دی کاشت لئی کیوں مشہور ہے؟ اوتھے دی ریتلی زمین تے گھٹ بارش دی وجہ توں چنا سوکھا اگ پیندا ہے جِتھے دوجے فصل نہیں ہوندے۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل جا هاري چڻي لاءِ زمين ڪيئن تيار ڪن ٿا؟", "تھل دے کسان چنے لئی زمین کیویں تیار کردے نیں؟ اوتھے دے کسان زیادہ ہل نہیں چلاؤندے تے اکثر بارش دی نمی اُتے انحصار کردے نیں۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل ۾ چڻي جي ننڍن ٻوٽن کي ڪهڙو وڏو خطرو هوندو آهي؟", "تھل وچ چنے دے چھوٹے بوٹیاں نوں کیہڑا وڈا خطرہ ہوندا ہے؟ اکتوبر تے نومبر دیاں ریتلیاں ہواواں بوٹیاں نوں اکھاڑ دیندیاں نیں جاں مٹی وچ دبا دیندیاں نیں۔", "صوبائي: مرڪز پنجاب"),
    ("ٿل جا هاري ريتلي هوائن کان ڪيئن بچندا آهن؟", "تھل دے کسان ریتلیاں ہواواں توں کیویں بچدے نیں؟ کسان پچھلی فصل دے مڈھ (Stubble) زمین وچ چھڈ دیندے نیں جیہڑے ہواواں نوں روکدے نیں۔", "صوبائي: مرڪز پنجاب"),
    ("ٿل ۾ چڻي جو فصل باراني آهي يا آبپاش؟", "تھل وچ چنے دی فصل بارانی ہے یا آبپاش؟ ایہہ فصل مکمل طور اُتے بارش اُتے انحصار کردی ہے، تے سردیاں دی بارشاں نال ایہدی نشوونما ہوندی ہے۔", "صوبائي مرڪز: پنجاب"),
    ("جيڪڏهن سياري جي برسات نه پوي ته ڇا ٿيندو؟", "جے سردیاں وچ بارش نہ ہووے تاں کیہہ ہووے گا؟ بارش نہ ہون دی صورت وچ فصل سُک جاندی ہے تے پیداوار نہ ہون دے برابر رہ جاندی ہے۔", "صوبائي مرڪز: پنجاب"),
    ("فيبروري جي برسات جو ٿل جي فصل تي ڇا اثر پوندو آهي؟", "فروری دی بارش دا تھل دی فصل اُتے کیہہ اثر پیندا ہے؟ سِرے دے ویلے دی بارش نال پیداوار ودھ جاندی ہے، پر جے نمی ودھ ہووے تاں جھلساؤ (Blight) دا خطرہ ودھ جاندا ہے۔", "صوبائي مرڪز: پنجاب"),
    ("جھلساؤ (Ascochyta Blight) پنجاب ۾ ڇو خطرناڪ سمجهيو وڃي ٿو؟", "جھلساؤ (Ascochyta Blight) نوں پنجاب وچ کیوں خطرناک سمجھیا جاندا ہے؟ ایہہ بیماری کجھ دناں وچ ساری فصل نوں تباہ کر سکدی ہے۔", "صوبائي مرڪز: پنجاب"),
    ("سائنسدان ٿل جي هارين جي ڪيئن مدد ڪري رهيا آهن؟", "سائنسدان تھل دے کساناں دی کیویں مدد کر رہے نیں؟ سائنسدان ایسی قسماں تیار کر رہے نیں جیہڑیاں بیماری تے خشکی دا چنگی طرح مقابلہ کر سکن۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل جا هاري ڀاڻ ڇو گهٽ استعمال ڪن ٿا؟", "تھل دے کسان کھاد کیوں گھٹ استعمال کردے نیں؟ کیوں جو ایہہ فصل بارش اُتے انحصار کردی ہے، ایس لئی جے بارش نہ ہوئی تاں کھاد دا خرچہ ضائع ہو جائے گا۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل ۾ چڻي کي گهڻي يوريا ڏيڻ جو ڇا نقصان آهي؟", "تھل وچ چنے نوں زیادہ یوریا دین دا کیہہ نقصان ہے؟ زیادہ یوریا دین نال بوٹے دی نشوونما تیز ہو جاندی ہے، جیہدی وجہ نال زمین دی نمی ختم ہو جاندی ہے۔", "صوبائي مرڪز: پنجاب"),
    ("ڇا ٿل ۾ جڙي ٻوٽيون وڏو مسئلو آهن؟", "کیہہ تھل وچ جڑی بوٹیاں وڈا مسئلہ نیں؟ ریتلی زمین وچ جڑی بوٹیاں گھٹ ہوندیاں نیں، پر فیر وی پیازی فصل دا پاݨی کھچ لیندی ہے۔", "صوبائي مرڪز: پنجاب"),
    ("ٿل جي معيشت ۾ چڻي جو ڇا ڪردار آهي؟", "تھل دی معیشت وچ چنے دا کیہہ کردار ہے؟ ایہہ کساناں دی مکھی فصل ہے جیہدے توں پورے سال دا خرچہ نکلدا ہے۔", "صوبائي: مرڪز پنجاب"),
    ("ڇا ٿل جي دڙن تي مشينن سان لڻائي ممڪن آهي؟", "کیہہ تھل دیاں ٹلیاں اُتے مشیناں نال کٹائی ممکن ہے؟ ڈونگھی زمین اُتے مشیناں چلاؤݨا مشکل ہوندا ہے، ایس لئی کٹائی اجے وی ہتھ نال ای کیتی جاندی ہے۔", "صوبائي: مرڪز پنجاب"),
    ("ٿل ۾ سيءُ (Frost) ڇو خطرناڪ آهي؟", "تھل وچ کورا (Frost) کیوں خطرناک ہے؟ رات نوں ریتلی زمین بہت تیزی نال ٹھنڈی ہوندی ہے، جنوری دی ٹھنڈ پھلاں نوں ساڑ دیندی ہے۔", "صوبائي: مرڪز پنجاب"),
    ("پنجاب ۾ سيءَ کان ڪيئن بچاءُ ڪيو وڃي ٿو؟", "پنجاب وچ کورا توں کیویں بچاؤ کیتا جاندا ہے؟ کاشت کجھ ویلے دی تاخیر نال کیتی جاندی ہے تاکہ پھل کورے دے موسم مگروں آوݨ۔", "صوبائي: مرڪز پنجاب"),
